const $ = (sel) => document.querySelector(sel);

const inp = $('#inp');
const outWord = $('#outWord');
const outLabel = $('#outLabel');
const outWhy = $('#outWhy');
const go = $('#go');
const clearBtn = $('#clear');
const forceOxytone = $('#forceOxytone');
const forceBarytone = $('#forceBarytone');
const showBreathing = $('#showBreathing');

// --- Utilities ---
const COMBINING = /[\u0300-\u036f]/g;

function normalizeGreek(s){
  return (s||'')
    .trim()
    .replace(/[··]/g,'·')
    .replace(/\s+/g,' ');
}

function stripDiacritics(s){
  // Remove combining marks after NFD; keeps base letters.
  return s.normalize('NFD').replace(COMBINING,'').normalize('NFC');
}

function lowerGreek(s){
  return stripDiacritics(s).toLowerCase();
}

function isGreekLetter(ch){
  const code = ch.codePointAt(0);
  return (code >= 0x0370 && code <= 0x03FF) || (code >= 0x1F00 && code <= 0x1FFF);
}

function lastGreekWord(s){
  // pick last token containing Greek letters
  const parts = s.split(/\s+/).filter(Boolean);
  for(let i=parts.length-1;i>=0;i--){
    if([...parts[i]].some(isGreekLetter)) return parts[i];
  }
  return s.trim();
}

function splitNounVerb(raw){
  // Accept formats: "noun,verb" or "noun ; verb" etc.
  const s = normalizeGreek(raw);
  const m = s.split(/\s*[,;]\s*/);
  if(m.length >= 2) return { noun: m[0], verb: m.slice(1).join(',') };
  return { noun: s, verb: '' };
}

function countSyllablesToy(word){
  // Toy syllable count: count vowel groups.
  const w = lowerGreek(word);
  const vowels = 'αεηιουω';
  let count = 0;
  let prevVowel = false;
  for(const ch of w){
    const isV = vowels.includes(ch);
    if(isV && !prevVowel) count++;
    prevVowel = isV;
  }
  return count;
}

function endsWithRos(word){
  const w = lowerGreek(word);
  return w.endsWith('ρος');
}

function hasDoubleConsonantPattern(word){
  const w = lowerGreek(word);
  return /(ρρ|σσ|κκ|ττ|νν|λλ|μμ|ππ)/.test(w);
}

function verbPenultLooksLikeE_EI_AI(verb){
  // Very rough: look at last 2-4 letters for ει/αι or a penult epsilon.
  const v = lowerGreek(verb).replace(/[^α-ω]/g,'');
  if(v.length < 3) return false;

  // Find last vowel positions
  const vowels = 'αεηιουω';
  const vowelIdx = [];
  for(let i=0;i<v.length;i++) if(vowels.includes(v[i])) vowelIdx.push(i);
  if(vowelIdx.length < 2) return false;

  const penultVowelPos = vowelIdx[vowelIdx.length-2];
  const penult = v.slice(penultVowelPos, penultVowelPos+2); // maybe diphthong

  if(penult.startsWith('ε')) return true;
  if(penult.startsWith('ει')) return true;
  if(penult.startsWith('αι')) return true;
  return false;
}

function addAcuteToVowel(vowel){
  const map = {
    'α':'ά','ε':'έ','η':'ή','ι':'ί','ο':'ό','υ':'ύ','ω':'ώ',
    'Α':'Ά','Ε':'Έ','Η':'Ή','Ι':'Ί','Ο':'Ό','Υ':'Ύ','Ω':'Ώ'
  };
  return map[vowel] || vowel;
}

function accentPenult(word){
  // Put acute on the penult vowel (toy). Assumes ends in -ρος.
  const w = stripDiacritics(word);
  const chars = [...w];
  const vowels = new Set(['α','ε','η','ι','ο','υ','ω','Α','Ε','Η','Ι','Ο','Υ','Ω']);
  const vowelPositions = [];
  for(let i=0;i<chars.length;i++) if(vowels.has(chars[i])) vowelPositions.push(i);
  if(vowelPositions.length < 2) return w;
  const pos = vowelPositions[vowelPositions.length-2];
  chars[pos] = addAcuteToVowel(chars[pos]);
  return chars.join('');
}

function accentUltima(word){
  // Put acute on the ultima vowel.
  const w = stripDiacritics(word);
  const chars = [...w];
  const vowels = new Set(['α','ε','η','ι','ο','υ','ω','Α','Ε','Η','Ι','Ο','Υ','Ω']);
  for(let i=chars.length-1;i>=0;i--){
    if(vowels.has(chars[i])){ chars[i] = addAcuteToVowel(chars[i]); break; }
  }
  return chars.join('');
}

function addBreathingToy(word){
  // Add rough breathing to initial iota/upsilon by default; smooth to alpha/epsilon/omicron/omega/eta.
  // Only if word begins with a vowel and has no breathing already (we stripped diacritics anyway).
  const w = stripDiacritics(word);
  const first = w[0];
  if(!first) return w;
  const rough = {
    'ι':'ἱ','Ι':'Ἱ',
    'υ':'ὑ','Υ':'Ὑ',
    'ρ':'ῥ','Ρ':'Ῥ'
  };
  const smooth = {
    'α':'ἀ','Α':'Ἀ',
    'ε':'ἐ','Ε':'Ἐ',
    'η':'ἠ','Η':'Ἠ',
    'ο':'ὀ','Ο':'Ὀ',
    'ω':'ὠ','Ω':'Ὠ',
    'ι':'ἰ','Ι':'Ἰ',
    'υ':'ὐ','Υ':'Ὑ'
  };
  // Prefer rough for iota/upsilon/rho; else smooth.
  let repl = rough[first] || smooth[first];
  if(!repl) return w;
  return repl + w.slice(1);
}

// --- Passage-inspired exceptions (toy list) ---
const EXCEPTIONS = new Map([
  // key: stripped lowercase
  ['φορος(wind)','oxytone'],
  ['φορoς(wind)','oxytone'],
  ['φορος(ανεμος)','oxytone'],
  ['φορος','barytone'], // default meaning 'tribute' etc.
  ['ορος','barytone'],
  ['ορος(whey)','oxytone'],
  ['ορος(γαλα)','oxytone'],
  ['ορρος','barytone'],
  ['βορος','oxytone'],
  ['χορος','oxytone'],
  ['σορος','oxytone'],
  ['τορος','oxytone'],
  ['δορος','oxytone']
]);

function classify(rawNoun, rawVerb){
  const noun = normalizeGreek(rawNoun);
  const verb = normalizeGreek(rawVerb);

  const nounKey = lowerGreek(noun).replace(/\s+/g,'');
  const note = lowerGreek(rawNoun).replace(/\s+/g,'');

  // detect parenthetical gloss like "φορος (wind)"
  let glossKey = nounKey;
  const glossMatch = note.match(/^([^()]+)\(([^)]+)\)$/);
  if(glossMatch){
    const base = glossMatch[1].trim();
    const gloss = glossMatch[2].trim();
    glossKey = lowerGreek(base).replace(/\s+/g,'') + '(' + lowerGreek(gloss).replace(/\s+/g,'') + ')';
  }

  // Force toggles
  if(forceOxytone.checked && !forceBarytone.checked){
    return {type:'oxytone', why:'Forced oxytone by toggle.'};
  }
  if(forceBarytone.checked && !forceOxytone.checked){
    return {type:'barytone', why:'Forced barytone by toggle.'};
  }

  // Exceptions
  if(EXCEPTIONS.has(glossKey)){
    const t = EXCEPTIONS.get(glossKey);
    const why = (glossKey.includes('(wind)') || glossKey.includes('ανεμος'))
      ? 'Named distinction in the passage: φορός “wind” is oxytone.'
      : (glossKey.startsWith('ορος(') ? 'Named distinction in the passage: ὀρός “whey” is oxytone.' : 'Listed/marked in the passage as oxytone/barytone.' );
    return {type:t, why};
  }

  // Only attempt rule if -ρος
  if(!endsWithRos(noun)){
    return {type:'unknown', why:'Toy focuses on disyllables ending in -ρος. Your input does not look like -ρος.'};
  }

  const syl = countSyllablesToy(noun);
  if(syl !== 2){
    return {type:'unknown', why:`Toy rule is for disyllabic -ρος words. I counted ~${syl} syllable(s). (Very rough.)`};
  }

  // Double consonant pattern -> barytone (ὄρρος-type)
  if(hasDoubleConsonantPattern(noun)){
    return {type:'barytone', why:'Looks like a “double consonant” pattern (e.g. ρρ/σσ/κκ…), which the passage treats as barytone (ὄρρος-type).'};
  }

  // If verb provided and penult looks like ε/ει/αι -> barytone (σπόρος-type)
  if(verb && verbPenultLooksLikeE_EI_AI(verb)){
    return {type:'barytone', why:'Given a verb whose penult looks like ε/ει/αι → prefer barytone (σπόρος-type) per the passage.'};
  }

  // Otherwise: default to oxytone for appellative/adjective feel
  return {type:'oxytone', why:'No derivation clue detected → toy defaults to oxytone (ἱρός/σιρός-type).'};
}

function render(){
  const raw = normalizeGreek(inp.value);
  if(!raw){
    outWord.textContent = '—';
    outLabel.textContent = '—';
    outWhy.textContent = 'Enter something above.';
    return;
  }

  const {noun, verb} = splitNounVerb(raw);
  const nounWord = lastGreekWord(noun);

  const cls = classify(nounWord, verb);

  let base = stripDiacritics(nounWord);
  if(showBreathing.checked) base = addBreathingToy(base);

  let accented = base;
  if(cls.type === 'barytone') accented = accentPenult(base);
  else if(cls.type === 'oxytone') accented = accentUltima(base);

  outWord.textContent = accented;

  const labelMap = {
    barytone: 'Barytone guess (acute on penult): …όρος',
    oxytone: 'Oxytone guess (acute on ultima): …ρός',
    unknown: 'No confident guess'
  };
  outLabel.textContent = labelMap[cls.type] || '—';

  const extra = verb ? `\nVerb clue: ${stripDiacritics(verb)}` : '';
  outWhy.textContent = cls.why + extra;
}

// --- Events ---

go.addEventListener('click', render);
inp.addEventListener('keydown', (e)=>{ if(e.key === 'Enter') render(); });
clearBtn.addEventListener('click', ()=>{ inp.value=''; render(); inp.focus(); });

forceOxytone.addEventListener('change', ()=>{
  if(forceOxytone.checked) forceBarytone.checked = false;
  render();
});
forceBarytone.addEventListener('change', ()=>{
  if(forceBarytone.checked) forceOxytone.checked = false;
  render();
});
showBreathing.addEventListener('change', render);

for(const b of document.querySelectorAll('.chip')){
  b.addEventListener('click', ()=>{ inp.value = b.dataset.fill; render(); inp.focus(); });
}

render();

